// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Moda, giyim tarihi ve tekstil terimleri (kolay).
const ozCulture9Kolay = <(String, String, List<String>, String)>[
  ('Pamuk lifi, pamuk bitkisinin hangi bölümünden elde edilir?', 'Tohumları saran tüylerden', ['Gövdedeki kabuğun hemen altından', 'Yaprak damarlarından', 'Kök liflerinden'], 'Pamuk bir tohum lifidir; koza açıldığında tohumların çevresindeki beyaz tüyler toplanıp lif olarak kullanılır.'),
  ('Tarladan toplanan ham pamuk iplik fabrikasına gönderilmeden önce içindeki tohumlardan ayrılmalıdır. Bunun için hangi işlem yapılır?', 'Çırçırlama', ['Havuzlama işlemi', 'Kırkım', 'Büküm'], 'Çırçır makinesi pamuk liflerini tohumdan ayırır; ayrılan tohum çiğit adıyla yağ ve yem üretiminde kullanılır.'),
  ('Bir tüccar patates çuvalı ve kalın halat üretmek için ucuz ve dayanıklı bir bitkisel lif arıyor. Seçenekler arasında en uygun lif hangisidir?', 'Jüt', ['Merinos yünü', 'Kapok', 'İpek'], 'Jüt, Ganj deltasında yoğun olarak yetiştirilen ucuz bir sap lifidir; \'altın lif\' olarak da anılır ve çuval yapımıyla özdeşleşmiştir.'),
  ('Bir yün üreticisi tene batmayan, çok ince lifli yün elde etmek için sürüsüne hangi koyun ırkını katmalıdır?', 'Merinos', ['Karaman', 'Akkaraman', 'Kıvırcık'], 'Merinos koyunu Orta Çağ İspanya\'sında geliştirilmiş, çok ince lifli yünüyle dünyaya yayılmış bir ırktır.'),
  ('Bir çoban ilkbaharda koyunlarının yününü makasla kesip tek parça yapağı hâlinde topluyor. Yaptığı işin adı nedir?', 'Kırkım', ['Hallaç', 'Tarama', 'Çırçırlama'], 'Kırkım koyun yününün kesilmesidir; elde edilen tek parça yün örtüsüne yapağı denir.'),
  ('Ağaç hamurundaki selülozun kimyasal olarak çözülüp düzelerden geçirilerek yeniden lif hâline getirilmesiyle üretilen lif hangisidir?', 'Viskon', ['Polyester', 'Akrilik', 'Naylon'], 'Viskon, doğal selülozdan üretilen rejenere (yarı sentetik) bir liftir; ipeğe benzeyen parlaklığıyla \'suni ipek\' diye de anılmıştır.'),
  ('Plastik su şişeleriyle aynı polimer ailesinden yapılan ve geri dönüştürülmüş şişelerden de üretilebilen sentetik lif hangisidir?', 'Polyester', ['Viskon', 'Elastan', 'Aramid'], 'Su şişeleri PET (polietilen tereftalat) adlı bir polyesterden yapılır; eritilip lif hâline getirilerek giysilerde kullanılabilir.'),
  ('Bir üretici yün kazak görünümünde ama daha ucuz ve güveden etkilenmeyen kazaklar üretmek istiyor. Hangi sentetik lifi seçmesi en uygundur?', 'Akrilik', ['Naylon', 'Viskon', 'Aramid'], 'Akrilik lifler yüne benzer bir dolgunluk ve sıcaklık verir; yünden ucuzdur ve güveden etkilenmez.'),
  ('Bir kot üreticisi pantolonlarının vücudu sarıp esnemesini istiyor. Pamuğa yüzde birkaç oranında hangi lifi katmalıdır?', 'Elastan', ['Akrilik lif', 'Keten', 'Viskon'], 'Elastan (spandeks) boyunun birkaç katına uzayıp eski hâline dönebilir; kumaşa yüzde birkaç oranında katılması bile esneklik sağlar.'),
  ('Bir lif örneği yakıldığında alevden çekilince söndüğü, eriyip ucunda sert ve siyah bir boncuk bıraktığı görülüyor. Bu lif büyük olasılıkla hangisidir?', 'Polyester', ['Pamuk', 'Yün', 'Keten lifi'], 'Sentetik lifler yanarken erir ve sert boncuk bırakır; pamuk ve keten kâğıt gibi yanar, yün ise yanık saç kokusu verir.'),
  ('Kısa liflerin çekilip bükülerek sürekli bir iplik hâline getirilmesi işlemine ne ad verilir?', 'Eğirme', ['Dokuma', 'Örme', 'Apreleme'], 'Eğirme, kesikli lifleri inceltip büküm vererek ipliğe dönüştürür; büküm lifleri birbirine tutturur.'),
  ('Lifleri iplik hâline getirmek için elle ya da ayakla çevrilen tekerlekli geleneksel eğirme aracına ne ad verilir?', 'Çıkrık', ['Kirkit tarağı', 'Gergef', 'Mekik'], 'Çıkrık, tekerleğin döndürdüğü bir iğ ile lifleri büküp sarar; elle eğirmeye göre işi çok hızlandırmıştır.'),
  ('Atkı ipliğinin sırayla bir çözgünün üstünden, bir sonrakinin altından geçtiği en basit dokuma örgüsüne ne ad verilir?', 'Bezayağı', ['Dimi', 'Saten', 'Jakar örgüsü'], 'Bezayağı en sık bağlantılı ve en basit örgüdür; poplin, patiska ve kanvas gibi pek çok kumaş bu örgüyle dokunur.'),
  ('Bir kot pantolonun yüzeyine yakından bakıldığında çapraz uzanan ince çizgiler görülür. Bu görünüm hangi dokuma örgüsünden kaynaklanır?', 'Dimi', ['Bezayağı', 'Saten', 'Panama'], 'Dimi örgüsünde bağlantı noktaları her sırada bir iplik kayarak diyagonal çizgiler oluşturur; kot kumaşı tipik bir dimidir.'),
  ('Bir terzi yazlık erkek gömleği için ince, düzgün yüzeyli ve sık dokunmuş bir pamuklu kumaş arıyor. Seçenekler arasında en uygunu hangisidir?', 'Poplin', ['Kanvas', 'Gabardin', 'Kadife'], 'Poplin ince çözgü ve biraz kalın atkıyla sık dokunur; yüzeyi düzgün ve hafif parlak olduğu için gömleklik olarak sevilir.'),
  ('Bir yağmurluk üreticisi kaplama kullanmadan, yalnız çok sık dimi dokusu sayesinde suyu iten sağlam bir kumaş arıyor. Hangisini seçmelidir?', 'Gabardin', ['Şifon', 'Flanel', 'Tül'], 'Gabardin sıkı dimi örgüsüyle su itici bir yapıya sahiptir; 19. yüzyılın sonunda yağmurluk kumaşı olarak ün kazanmıştır.'),
  ('Bir modacı gece elbisesine hafif, yarı saydam ve akışkan bir üst katman eklemek istiyor. Hangi kumaşı seçmelidir?', 'Şifon', ['Kanvas', 'Tvid', 'Gabardin'], 'Şifon yüksek bükümlü ince ipliklerle seyrek dokunur; hafif, saydam ve dökümlüdür.'),
  ('Bir kostümcü, oyuncu yürüdükçe hışırdayan, sert ve parlak bir balo eteği istiyor. Hangi kumaşı seçmelidir?', 'Tafta', ['Flanel', 'Kadife', 'Jarse'], 'Tafta sık dokunmuş, gergin ve parlak bir kumaştır; sürtündükçe hışırdaması onun tanınan özelliğidir.'),
  ('Sonbahar için yüzeyi boydan boya kabarık havlı çubuklarla kaplı, dayanıklı bir pamuklu pantolon arayan birine hangi kumaş önerilir?', 'Fitilli kadife', ['İnce pamuklu poplin', 'Şifon', 'Krep saten'], 'Fitilli kadifede (kaşe kadife değil, İng. corduroy) hav sıraları paralel fitiller hâlinde dizilir; fitil genişliği kumaşın türünü belirler.'),
  ('Kış için yumuşak, tüylü yüzeyli ve sıcak tutan kareli bir gömlek isteyen müşteriye terzi hangi kumaşı önermelidir?', 'Flanel', ['Organze', 'Saten', 'Tafta'], 'Flanel yün ya da pamuktan dokunur ve şardonla tüylendirilir; bu tüyler hava hapsederek sıcak tutar.'),
  ('Bir atölye yelken ve çadır yapımı için kalın, sağlam ve sık dokunmuş bir bez arıyor. Seçenekler arasında hangisi uygundur?', 'Kanvas', ['Şifon', 'Organze', 'Saten'], 'Kanvas kalın ipliklerle sık dokunan dayanıklı bir bezdir; ressamların tuvali de bu kumaştandır.'),
  ('Örme kumaşı dokuma kumaştan ayıran temel yapı özelliği hangisidir?', 'İpliğin iç içe geçen ilmekler oluşturması', ['Atkı ve çözgü ipliklerinin dik açıyla kesişmesi', 'Liflerin yapıştırıcıyla bağlanması', 'Yalnız sentetik iplik kullanılması'], 'Örmede iplik ilmekler hâlinde birbirinin içinden geçirilir; dokumada ise iki iplik sistemi birbirini dik açıyla keser.'),
  ('Bir üretici ince, hafif ve tek katlı yuvarlak örme kumaştan klasik bisiklet yaka tişörtler üretmek istiyor. Kumaş olarak hangisini seçmelidir?', 'Süprem', ['Ribana', 'Kanvas', 'Gabardin'], 'Süprem tek plakalı yuvarlak örme makinelerinde üretilir; hafif ve yumuşak olduğu için tişört ve iç giyimde çok kullanılır.'),
  ('Bir tişört üreticisi yakaların ve kol ağızlarının giyildikçe bollaşmamasını, esneyip eski hâline dönmesini istiyor. Bu bölgelerde hangi örme kumaşı kullanmalıdır?', 'Ribana', ['Süprem', 'Pamuklu poplin', 'Tafta'], 'Ribanada düz ve ters ilmek sütunları sırayla dizilir; bu yapı kumaşa enine yüksek esneklik kazandırır.'),
  ('Türkçede giyim sektöründe \'triko\' sözcüğü genellikle neyi anlatır?', 'Örme kazak ve hırka gibi giysileri', ['Üç parçalı erkek takım elbiseyi', 'İpek dokuma gömlekleri', 'Deri ceket ve yelekleri'], 'Triko, Fransızca tricot (örgü) sözcüğünden gelir; kazak, hırka ve süveter gibi örme giysiler için kullanılır.'),
  ('Bir hastane bir kez kullanılıp atılacak ucuz önlük ve örtüler için iplik ve dokuma aşaması olmadan hızla üretilen bir tekstil malzemesi arıyor. Hangisi en uygundur?', 'Dokusuz yüzeyler', ['Çözgülü örmeler', 'Jakarlı dokumalar', 'Katlı iplikler'], 'Dokusuz yüzeyler (nonwoven) doğrudan lif tabakasından üretilir; hızlı ve ucuz oldukları için tek kullanımlık ürünlerde yaygındır.'),
  ('Kot pantolona eskimiş ve solmuş bir görünüm kazandırmak için büyük çamaşır makinelerinde süngertaşı parçalarıyla birlikte yıkama yapılır. Bu işleme ne ad verilir?', 'Taş yıkama', ['Asit baskı', 'Şardonlama', 'Merserizasyon'], 'Taş yıkamada (stone wash) süngertaşları kumaşı aşındırarak indigo boyayı yer yer söker ve kumaşı yumuşatır.'),
  ('Bir öğrenci beyaz bir tişörtü düğümleyip lastiklerle sıkıca bağladıktan sonra boyaya batırıyor; tişört açıldığında renkli halkalar görülüyor. Uygulanan teknik hangisidir?', 'Bağla-boya', ['Taş yıkama', 'Kalandırla kabartma baskı', 'Sanforlama'], 'Bağla-boyada ipin sıktığı yerler boyayı almaz; kumaş açıldığında halka ve sarmal desenler görülür.'),
  ('Tişörtlere desen basmak için mürekkebin gerili ince bir elekten rakleyle geçirildiği, her renk için ayrı şablon gereken baskı yöntemi hangisidir?', 'Serigrafi', ['Süblimasyon', 'Rotogravür', 'Ofset'], 'Serigrafide (elek baskı) desen dışındaki elek gözenekleri kapatılır; mürekkep yalnız açık kalan yerlerden kumaşa geçer.'),
  ('Altı farklı renk içeren bir logo, tişörtlere serigrafi yöntemiyle basılacaktır. Her renk ayrı basıldığına göre kaç elek şablonu hazırlanmalıdır?', '6', ['1', '3', '12'], 'Serigrafide her renk ayrı bir elekle basılır; altı renk için altı şablon gerekir.'),
  ('Bir tişörtün renginin güneş ışığına uzun süre maruz kaldığında solmaya karşı gösterdiği direnç hangi terimle anlatılır?', 'Işık haslığı', ['Yıkama haslığı', 'Sürtme haslığı', 'Ter haslığı'], 'Haslık, rengin dış etkilere dayanıklılığıdır; güneşe karşı olanı ışık haslığı, yıkamaya karşı olanı yıkama haslığı diye ölçülür.'),
  ('Bir modacı 1960\'lardan esinlenen koleksiyonu için siyah-beyaz, kırık karelerden oluşan ve köpek dişini andıran klasik bir desen seçiyor. Bu desenin Türkçedeki yaygın adı nedir?', 'Kazayağı', ['Balıksırtı', 'Pötikare', 'Prens dö gal'], 'Kazayağı (Fr. pied-de-poule, tavuk ayağı) siyah-beyaz ceket ve eteklerde sık görülen bir dimi deseninden doğar.'),
  ('Kırık dimi örgüsüyle elde edilen, sıra sıra V biçimli çizgilerin bir balık iskeletini andırdığı ceketlik desen hangisidir?', 'Balıksırtı', ['Kazayağı', 'Pötikare', 'Puantiye'], 'Balıksırtı desende dimi çizgisinin yönü belli aralıklarla tersine döner; bu da bir balığın kılçıklarına benzeyen bir görünüm verir.'),
  ('Golf sahasında giyilecek bir süveter için baklava dilimleri ve bunların üzerinden geçen ince çapraz çizgilerden oluşan desen isteyen müşteriye hangi desen gösterilmelidir?', 'Argyle', ['Tartan', 'Pötikare', 'Kazayağı'], 'Argyle deseni İskoçya\'nın batısındaki Argyll bölgesinin klan desenlerinden esinlenmiştir; golf modasıyla da yaygınlaşmıştır.'),
  ('Piknik örtüsü dikecek biri, beyazla kırmızının eşit genişlikteki şeritlerinin kesişmesinden oluşan küçük kareli bir kumaş arıyor. Aradığı desen hangisidir?', 'Pötikare', ['Balıksırtı', 'Kazayağı', 'Argyle'], 'Pötikarede kesişme yerlerinde koyu, yalnız tek yönde renkli şerit olan yerlerde ara ton oluşur; desen iki yüzde de aynı görünür.'),
  ('Bir terzi düz kesilmiş bir bluzun göğüs ve bel kısmında bol durduğunu görüyor ve kumaşı uca doğru sivrilen üçgen kıvrımlarla içeri alarak bedene oturtuyor. Bu kıvrımlara ne ad verilir?', 'Pens', ['Pili', 'Biye', 'Teyel'], 'Pens, kumaştan üçgen biçiminde bir parça içeri alınarak dikilmesidir; böylece düz kumaş üç boyutlu bir biçim kazanır.'),
  ('Bir terzi okul eteğine hareket payı vermek için kumaşı eşit aralıklarla katlayıp ütüleyerek düzenli kıvrımlar oluşturuyor. Bu kıvrımlara ne ad verilir?', 'Pili', ['Pens', 'Biye', 'Tela'], 'Pililer kumaşın düzenli katlanmasıyla oluşur; bıçak pili, kutu pili ve akordeon pili gibi türleri vardır.'),
  ('Bir terzi kolsuz bir bluzun kavisli kol ağzını temizlemek için verev kesilmiş ince bir kumaş şeridini kenara dikiyor. Bu şeride ne ad verilir?', 'Biye', ['Tela', 'Astar', 'Pili'], 'Biye kumaştan 45 derece açıyla kesildiği için esner; kol ağzı ve yaka gibi kavisli kenarları düzgün kaplar.'),
  ('Bir terzi örme kumaştan diktiği tişörtün iç kenarlarının sökülmemesi için kenarları aynı anda kesip iplikle saran bir makine kullanıyor. Bu makine hangisidir?', 'Overlok', ['Reçme', 'İlik makinesi', 'Düz makine'], 'Overlok makinesi kenarı bıçakla düzeltirken iplik ilmekleriyle sarar; örme kumaşlarda esnek birleştirme dikişi olarak da kullanılır.'),
  ('Bir terzi provadan önce parçaları, sonradan kolayca sökebileceği büyük adımlı bir el dikişiyle geçici olarak birleştiriyor. Bu dikişe ne ad verilir?', 'Teyel', ['Biye', 'Pens', 'Nervür'], 'Teyel, provada giysinin uyumunu görmek ve parçaların kaymasını önlemek için atılır; asıl dikişten sonra sökülür.'),
  ('Bir gömlek üreticisi yakaların yıkamadan sonra yumuşayıp devrildiği yönünde şikâyet alıyor. Sorunu çözmek için yakanın iki kumaş katı arasına ne eklemelidir?', 'Tela', ['Biye', 'Astar', 'Pili'], 'Tela çoğunlukla ısıyla yapışan bir ara katmandır; yaka, manşet ve pat gibi bölgelere sertlik ve biçim verir.'),
  ('Bir terzi yün ceketin gömlek üzerinde kolayca kaymasını ve iç dikişlerin görünmemesini istiyor. Ceketin içine ne dikmelidir?', 'Astar', ['Tela', 'Biye', 'Kup'], 'Astar ceketin içine dikilir; kaygan yüzeyi sayesinde ceket gömleğin üzerinde kolayca kayar.'),
  ('El dikişinde iğneyi kumaşa iterken parmağı korumak için parmağa takılan çukurlu küçük metal başlığa ne ad verilir?', 'Yüksük', ['Mekik', 'Kirmen', 'Makara'], 'Yüksüğün yüzeyindeki küçük çukurlar iğnenin arkasının kaymadan itilmesini sağlar.'),
  ('Kalıp çizgisinin dışında bırakılan ve parçaları birbirine dikmek için kullanılan kumaş payına ne ad verilir?', 'Dikiş payı', ['Pastal payı', 'Bolluk payı', 'Kesim payı'], 'Dikiş payı genellikle 1–1,5 santimetredir; bu pay olmazsa parçalar dikildiğinde giysi küçülür.'),
  ('Terzilikte giysi parçalarının ölçülere göre kâğıda çizilmiş şablonuna ne ad verilir?', 'Patron', ['Pastal', 'Prova', 'Teyel'], 'Patron (kalıp), kumaşın kesileceği parçaların biçimini gösterir; konfeksiyonda farklı bedenler için seri hâline getirilir.'),
  ('Bir müşteri gelinliği bitmeden terzisine gidip teyelli hâldeki giysiyi giyiyor; terzi bel ve boy düzeltmelerini işaretliyor. Bu aşamaya ne ad verilir?', 'Prova', ['Pastal', 'Teyel', 'Defile'], 'Provada giysi genellikle teyelli hâldedir; terzi bolluk, boy ve omuz gibi ayrıntıları müşterinin üzerinde düzeltir.'),
  ('Londra\'ya giden ve kendi ölçülerine göre elde dikilmiş geleneksel bir takım elbise yaptırmak isteyen bir turist, ısmarlama terzileriyle ünlü hangi sokağa gitmelidir?', 'Savile Row', ['Oxford Street', 'Baker Street', 'Downing Street'], 'Savile Row 19. yüzyıldan bu yana ısmarlama takım elbise terzileriyle özdeşleşmiştir.'),
  ('Bir terzi Çin giysilerinden esinlenen, boyunda dik duran ve önde birleşmeyen dar bant biçiminde bir gömlek yakası dikiyor. Bu yaka türü hangisidir?', 'Hakim yaka', ['Apaş yaka', 'Şal yaka', 'Kayık (bateau) yaka'], 'Hakim yaka (mandarin yaka) dar bir şerit hâlinde boyunda dik durur; geleneksel Çin giysilerinden esinlenmiştir.'),
  ('Soğuk bir kış günü boynunu tümüyle örtecek, katlanarak giyilen yüksek yakalı bir kazak arayan biri hangi yaka türünü seçmelidir?', 'Balıkçı yaka', ['Kayık (bateau) yaka', 'Apaş yaka', 'Hakim yaka'], 'Balıkçı yaka (boğazlı yaka) boynu sıcak tutar; adı denizcilerin giydiği kalın kazaklarla ilişkilendirilir.'),
  ('Omuzlarını ve köprücük kemiklerini öne çıkaracak, bir omuzdan öbürüne yatay açılan sığ bir yaka isteyen müşteriye hangi yaka önerilmelidir?', 'Kayık yaka', ['V yaka', 'Balıkçı yaka', 'Hakim yaka'], 'Kayık yaka (Fr. bateau, kayık) önde ve arkada sığdır, yanlara doğru geniş açılır.'),
  ('Bir terzi kolları ayrı dikmek yerine bedenle birlikte tek parça keserek kimono esinli bir bluz hazırlıyor. Ortaya çıkan kol türü hangisidir?', 'Japone kol', ['Reglan kol', 'Takma kol', 'Prenses kol'], 'Japone kolda kol ile beden arasında dikiş yoktur; kimono kesiminden esinlenmiştir ve omuz hattı yumuşak düşer.'),
  ('Bir dansçı döndükçe dalga dalga açılan bir etek istiyor; terzi de kumaşı tam daire biçiminde kesiyor. Ortaya çıkan etek türü hangisidir?', 'Kloş etek', ['Kalem etek', 'Tulip etek', 'Pareo etek'], 'Kloş etek daire kesimi sayesinde belde düz, eteğin ucunda geniş ve dalgalı düşer.'),
  ('İş toplantıları için belden dize kadar vücuda oturan, aşağıya doğru genişlemeyen dar bir etek arayan birine hangi etek önerilmelidir?', 'Kalem etek', ['Kloş etek', 'Pileli etek', 'Volanlı etek'], 'Kalem etek ince ve düz siluetiyle iş giyiminde klasikleşmiştir; yürümeyi kolaylaştırmak için genellikle arkasında yırtmaç bulunur.'),
  ('Omuzlardan ya da belden aşağıya bir harfin iki bacağı gibi düzgünce genişleyen elbise ve etek siluetine ne ad verilir?', 'A kesim', ['H kesim', 'Y kesim', 'T kesim'], 'A kesim üstte dar, aşağı doğru genişleyen bir biçimdir; bu adı 1955\'te Christian Dior\'un koleksiyonu yaygınlaştırmıştır.'),
  ('Geniş paçalı olduğu için ayakta dururken etek gibi görünen pantolon türüne ne ad verilir?', 'Pantolon etek', ['Kalem etek', 'Tulum', 'Tayt'], 'Pantolon etek (culotte) bacakları ayrı olduğu hâlde bolluğu sayesinde etek görünümü verir; bisiklete binmek için de kullanılmıştır.'),
  ('Bir bale okulunun yıl sonu gösterisi için balerinlere kat kat sert tülden kısa ve kabarık etekler dikiliyor. Bu eteklerin adı nedir?', 'Tütü', ['Kilt', 'Pareo', 'Sarong'], 'Tütü, bacak hareketlerinin görünmesini sağlayan kısa ve yatay açılan bir bale eteğidir.'),
  ('Bir doğa yürüyüşçüsü bacak yanlarında büyük körüklü cepler bulunan, çok eşya taşıyabileceği bir pantolon arıyor. Hangi pantolon türünü seçmelidir?', 'Kargo pantolon', ['Jodhpur binici pantolonu', 'Kapri pantolon', 'Chino'], 'Kargo pantolonun büyük cepleri askerlerin malzeme taşımasını kolaylaştırmak için tasarlanmıştır.'),
  ('Binicilik dersine başlayan bir öğrenciye kalçada bol, dizden bileğe dar ve çizmeyle giyilmeye uygun bir pantolon öneriliyor. Bu pantolon hangisidir?', 'Jodhpur', ['Bermuda', 'Kapri', 'Chino'], 'Jodhpur pantolonu Hindistan\'ın Racastan bölgesindeki Jodhpur kentinin geleneksel giysisinden esinlenmiş ve 19. yüzyılda İngiliz biniciliğine geçmiştir.'),
  ('Dizin hemen üstünde biten, adını Atlas Okyanusu\'ndaki bir İngiliz denizaşırı toprağından alan şort türü hangisidir?', 'Bermuda şort', ['Kapri şort', 'Jodhpur binici şortu', 'Kargo şort'], 'Bermuda şortu adalarda iş giysisi olarak bile kabul görür; diz üstü uzunluğu ve düz kesimiyle tanınır.'),
  ('1970\'ler temalı bir kostüm için dizden sonra genişleyip bilekte çan biçimini alan bir pantolon isteyen birine hangi paça türü önerilmelidir?', 'İspanyol paça', ['Duble paça', 'Lastikli jogger paça', 'Dar boru paça'], 'İspanyol paça pantolonlar (bell-bottom) 1960\'ların sonu ve 1970\'lerde gençlik modasının simgelerinden biri olmuştur.'),
  ('Bel kemerli, apoletli ve çoğunlukla çift sıra düğmeli bej yağmurluğun İngilizce adı \'trench coat\', Birinci Dünya Savaşı\'nın hangi unsuruyla ilişkilidir?', 'Askerlerin savaştığı siperlerle', ['Savaş gemilerinin güverteleriyle', 'Süvari birliklerinin atlarıyla', 'Hava kuvvetlerinin uçaklarıyla'], 'Trench İngilizcede siper demektir; bu yağmurluk Birinci Dünya Savaşı\'nda siperlerdeki subaylar arasında yaygınlaşmıştır.'),
  ('Bir terzi önü birbirinin üzerine geniş binen ve iki sıra düğmeyle kapanan bir palto dikiyor. Bu kesimin adı nedir?', 'Kruvaze', ['Tek düğmeli', 'Reglan', 'Japone'], 'Kruvaze (Fr. croisé, çapraz) kesimde ön parçalar üst üste biner ve genellikle iki paralel sıra düğme bulunur.'),
  ('Rüzgârlı bir liman kentinde yaşayan biri lacivert, kalın yünlü, kruvaze ve geniş yakalı kısa bir palto arıyor. Aradığı palto hangisidir?', 'Kaban', ['Frak', 'Redingot', 'Pelerin'], 'Kaban (İng. peacoat) denizcilerin soğuk ve rüzgârlı güvertelerde giydiği kısa paltodan gelir.'),
  ('Bir davetiyede en resmî kıyafet düzeni olan \'white tie\' istendiğini gören bir erkek, beyaz papyonla birlikte hangi giysiyi giymelidir?', 'Frak', ['Smokin', 'Redingot', 'Blazer'], 'Frak, \'white tie\' denen en resmî kıyafet düzeninin temel parçasıdır; smokinde ise kuyruk bulunmaz.'),
  ('Tişörte bu adın verilmesinin nedeni nedir?', 'Düz serilince T harfine benzemesi', ['İlk kez Teksas\'ta üretilmesi', 'T biçimli bir yaka taşıması', 'Tenisçiler için tasarlanması'], 'Kolları yana açık biçimde düz serilen tişört T harfine benzer; ad İngilizce \'T-shirt\' ifadesinden gelir.'),
  ('Canlı çiçek ve tropik desenleriyle bilinen, kısa kollu, düz kesim ve pantolon üzerine salaş giyilen gömlek türü hangi yerle özdeşleşmiştir?', 'Hawaii', ['İskoçya', 'Norveç', 'Tibet'], 'Aloha gömleği olarak da bilinen Hawaii gömleği 20. yüzyılın ortasında turizmle tüm dünyada tanınmıştır.'),
  ('Kol düğmesi takmak isteyen biri, geriye katlanıp iki kat kullanılan manşetlere sahip bir gömlek arıyor. Hangi manşet türünü seçmelidir?', 'Duble (Fransız) manşet', ['Tek düğmeli manşet', 'Lastikli manşet', 'Ribanalı manşet'], 'Duble manşette manşet kendi üzerine katlanır ve iki yanındaki iliklerden kol düğmesi geçirilir; daha resmî gömleklerde kullanılır.'),
  ('Tabanı örülmüş jüt ipten yapılan, üst kısmı kanvas kumaştan olan ve Pireneler yöresinden yayılan yazlık ayakkabı hangisidir?', 'Espadril', ['Mokasen', 'Loafer', 'Brogue'], 'Espadrilin tabanı geleneksel olarak sarmal örülmüş jüt ipten yapılır; İspanya ve Fransa\'nın Pireneler bölgesinde yüzyıllardır giyilir.'),
  ('Karlı ve çamurlu havada işe giden biri deri ayakkabılarının ıslanmaması için ayakkabının üzerine kauçuk bir koruyucu geçiriyor. Bu koruyucunun adı nedir?', 'Galoş', ['Mokasen', 'Espadril', 'Yemeni'], 'Galoş kauçuktan yapılır ve ayakkabının üzerine geçirilerek onu su, kar ve çamurdan korur; varılan yerde çıkarılınca ayakkabı kuru kalır.'),
  ('Bir kunduracı tabanı aşınmış ama üst kısmı sağlam bir ayakkabının altına yeni bir taban parçası dikerek ayakkabıyı onarıyor. Yaptığı işin adı nedir?', 'Pençe', ['Kalıp', 'Fort', 'Saya'], 'Pençe vurmak, ayakkabının ömrünü uzatan geleneksel bir tamir işidir; saya ise ayakkabının üst (yüz) kısmıdır.'),
  ('Bir sihirbaz gösterisinde içinden tavşan çıkarılacak, yüksek ve düz tepeli klasik bir erkek şapkası gerekiyor. Bu şapka hangisidir?', 'Silindir şapka', ['Melon şapka', 'Kasket', 'Bere'], 'Silindir şapka 19. yüzyılda üst sınıf erkeklerin günlük ve resmî başlığıydı; sihirbazların tavşan çıkardığı şapka olarak da bilinir.'),
  ('Önünde kısa bir siperliği bulunan, yassı ve yumuşak kumaş şapkaya ne ad verilir?', 'Kasket', ['Bere', 'Fötr', 'Kanotiye'], 'Kasket işçi ve köylü giyiminde yaygın olmuş, Türkiye\'de de 20. yüzyılda en çok kullanılan başlıklardan biri olmuştur.'),
  ('Antik Mısır\'da giysilerin büyük çoğunluğunun ketenden dokunması en iyi hangi koşullarla açıklanır?', 'Keten bitkisinin Nil vadisinde yetişmesi ve sıcakta serin tutması', ['Mısır\'da hiç koyun yetiştirilmemesi', 'Çin ipeğinin Mısır\'a çok ucuza gelmesi', 'Pamuğun Mısır\'da kutsal sayılıp kullanılmaması'], 'Nil vadisinde yetişen keten Mısır\'ın temel giyim lifiydi; sıcak iklimde serin tutar ve ince dokunabilirdi. Yün ise tapınaklarda ve mezarlarda çoğu zaman uygunsuz sayılırdı.'),
  ('Jane Austen romanlarından uyarlanan bir filmde kadın oyuncuların elbiselerinde bel çizgisi göğsün hemen altındadır ve etek düz dökülür. Kostümcünün kullandığı siluet hangisidir?', 'Ampir siluet', ['Prenses siluet', 'Kum saati siluet', 'Balon siluet'], 'Ampir (Fr. Empire, imparatorluk) siluetinde elbise göğüs altından serbest düşer; antik Yunan heykellerinden esinlenmiştir.'),
  ('1861\'de eşi Prens Albert\'i kaybettikten sonra hayatının sonuna kadar siyah yas giysileri giyen ve yas modasını etkileyen hükümdar kimdir?', 'Kraliçe Victoria', ['II. Elizabeth', 'Marie Antoinette', 'Büyük Katerina'], 'Kraliçe Victoria\'nın uzun yası, 19. yüzyıl İngiltere\'sinde yas giysileri ve siyah takılar için büyük bir pazar oluşturmuştur.'),
  ('1920\'ler temalı bir partiye kısa kesilmiş saç, düşük belli düz bir elbise ve diz hizasında saçaklı bir etekle gelen bir kadın hangi dönem tipini canlandırmaktadır?', 'Flapper', ['Dandy', 'Hippi', 'Punk'], 'Flapper\'lar caz çağının simgesiydi; erkek çocuk görünümlü düz siluet (garçonne) ve kısa saç bu dönemin moda imgesi oldu.'),
  ('1947\'de \'New Look\' adıyla anılan Dior siluetinin tipik özelliği hangisidir?', 'İyice daraltılmış bel ve bol, uzun etek', ['Düşük bel ve diz üstü düz etek', 'Geniş vatkalı omuz ve dar etek', 'Göğüs altından düşen ince elbise'], 'Dior savaş yıllarının sade ve köşeli giysilerine karşı yuvarlak omuzlu, ince belli ve dolgun etekli kadınsı bir siluet önerdi.'),
  ('1960\'larda Londra\'daki butiği aracılığıyla mini eteğin yaygınlaşmasıyla özdeşleşen İngiliz modacı kimdir?', 'Mary Quant', ['Vivienne Westwood', 'Stella McCartney', 'Zandra Rhodes'], 'Mary Quant\'ın King\'s Road\'daki butiği gençlik modasının merkezlerinden biri oldu; mini etek onun adıyla birlikte anılır.'),
  ('Yves Saint Laurent\'ın 1965 koleksiyonundaki, kalın siyah çizgilerle bölünmüş kırmızı, sarı ve mavi bloklardan oluşan düz kesim elbiseler hangi ressamın resimlerinden esinlenmiştir?', 'Piet Mondrian', ['Pablo Picasso', 'Vincent van Gogh', 'Henri Matisse'], 'Mondrian\'ın geometrik soyut resimleri düz kesim jarse elbiselere aktarılmış ve sanat ile modanın en bilinen buluşmalarından biri olmuştur.'),
  ('1990\'lar temalı bir partiye ekose flanel gömlek, yırtık kot pantolon ve kaba botlarla gelen bir kişinin canlandırdığı moda akımı hangisidir?', 'Grunge', ['Punk', 'Disko', 'Preppy'], 'Grunge özensiz ve ikinci el görünümü benimsedi; kısa sürede podyumlara da taşındı.'),
  ('Fransızcada \'giymeye hazır\' anlamına gelen ve standart bedenlerde seri olarak üretilen giyimi anlatan terim hangisidir?', 'Prêt-à-porter', ['Haute couture', 'Sur mesure', 'Avant-garde'], 'Prêt-à-porter hazır giyimdir; haute couture ise kişiye özel ölçüyle elde dikilen yüksek terziliktir.'),
  ('Moda dünyasında \'dört büyük\' diye anılan moda haftalarının düzenlendiği kentler hangileridir?', 'New York, Londra, Milano ve Paris', ['Roma, Berlin, Tokyo ve Madrid', 'Paris, Viyana, Moskova ve Sidney', 'Londra, Barselona, Seul ve Rio'], 'Moda takviminin ana durakları bu dört kenttir; koleksiyonlar genellikle bu sırayla gösterilir.'),
  ('Birbiriyle kolayca kombinlenebilen, az sayıda zamansız temel parçadan oluşan gardırop anlayışına ne ad verilir?', 'Kapsül gardırop', ['Hızlı moda', 'Haute couture', 'Vintage'], 'Kapsül gardırop az parçayla çok sayıda kombin yapmayı hedefler; gereksiz alışverişi azaltan bir yaklaşım olarak da önerilir.'),
  ('Podyumda görülen trendleri birkaç hafta içinde düşük fiyatlı kopyalarla mağazalara taşıyan ve koleksiyonları çok sık yenileyen iş modeline ne ad verilir?', 'Hızlı moda', ['Yavaş moda', 'Haute couture', 'Ismarlama terzilik'], 'Hızlı moda üretim ve tüketimi hızlandırır; ucuzluğu nedeniyle yaygınlaşmış, ancak çevresel ve sosyal etkileri nedeniyle eleştirilmiştir.'),
  ('New York\'taki Metropolitan Sanat Müzesi Kostüm Enstitüsü yararına düzenlenen ve konukların her yıl belirlenen temaya göre giyindiği ünlü bağış gecesi hangisidir?', 'Met Gala', ['Oscar Töreni', 'Cannes Festivali', 'Tony Ödülleri'], 'Met Gala, Kostüm Enstitüsü\'nün yıllık sergisinin açılışıyla birlikte düzenlenir ve moda dünyasının en çok izlenen gecelerinden biridir.'),
  ('Atatürk\'ün 1925\'te şapka ve kıyafet devrimini halka tanıtmak için ziyaret ettiği ve elinde şapkayla konuşma yaptığı kent hangisidir?', 'Kastamonu', ['Konya', 'Sivas', 'Bursa'], 'Atatürk Ağustos 1925\'te Kastamonu ve İnebolu\'da şapkanın uygar giyimin bir parçası olduğunu anlatmış; Şapka Kanunu aynı yılın kasımında kabul edilmiştir.'),
  ('Şapka İktisası Hakkında Kanun Türkiye Büyük Millet Meclisi\'nde hangi yıl kabul edilmiştir?', '1925', ['1923', '1928', '1934'], 'Kanun 25 Kasım 1925\'te kabul edilmiş ve şapkayı Türk milletinin genel başlığı olarak belirlemiştir.'),
  ('1933\'te kurulan ve Kayseri, Nazilli gibi kentlerde dokuma fabrikaları açarak yerli kumaş üretimini yaygınlaştıran devlet kuruluşu hangisidir?', 'Sümerbank', ['Etibank', 'İş Bankası', 'Ziraat Bankası'], 'Sümerbank Birinci Beş Yıllık Sanayi Planı\'nın temel kuruluşlarındandı; dokuma fabrikalarıyla ucuz ve yerli kumaş üretimini sağladı.'),
  ('Torunu için hediye hazırlayan bir büyükanne, düğme yerine bağcıkla kapanan, yakasız ve yumuşak pamuklu bir bebek iç gömleği dikiyor. Diktiği giysinin adı nedir?', 'Zıbın', ['Mintan', 'Cepken', 'Salta'], 'Zıbın bebeğin hassas tenini korumak için yumuşak pamuktan dikilir; düğme yerine bağcık kullanılması bebeğin rahatı içindir.'),
  ('Ağı aşağıda, çok bol ve paçaları ayak bileğinde toplanan, Anadolu\'da kadın ve erkeklerin giydiği geleneksel pantolona ne ad verilir?', 'Şalvar', ['Tozluk', 'Pantolon etek', 'Tayt'], 'Şalvarın bolluğu oturup kalkmayı ve tarlada çalışmayı kolaylaştırır; kumaşı ve kesimi yöreden yöreye değişir.'),
  ('Kimono giyen bir kişi giysisini belde sabitlemek için beline geniş bir kuşak sarıp arkada bağlıyor. Bu kuşağın adı nedir?', 'Obi', ['Tabi', 'Geta', 'Haori'], 'Obi kimononun en dikkat çekici aksesuarlarından biridir; kadın obileri çok geniş ve süslü olabilir.'),
  ('Kendo dersine başlayan bir öğrenciye üst giysisinin altına giymesi için pilili, pantolon-etek görünümlü bir giysi veriliyor. Bu giysinin adı nedir?', 'Hakama', ['Obi', 'Furisode', 'Tabi'], 'Hakama eskiden samurayların giysisiydi; bugün kendo, aikido gibi sporlarda ve mezuniyet törenlerinde giyilir.'),
  ('Japonya\'da geleneksel sandalet giyecek bir turist, sandaletin kayışı parmak arasından geçebilsin diye başparmağı ayrı bölmeli bir çorap alıyor. Bu çorabın adı nedir?', 'Tabi', ['Geta', 'Obi', 'Haori'], 'Tabi\'nin ayrık başparmağı, kayışı parmak arasından geçen sandaletlerin rahatça giyilmesini sağlar.'),
  ('Kültür ipekböceği (Bombyx mori) yetiştirmeye karar veren bir çiftçinin işe başlamadan önce bahçesine bol miktarda hangi ağaçtan dikmesi gerekir?', 'Dut', ['Meşe', 'Söğüt', 'Kavak'], 'Kültür ipekböceği neredeyse yalnız dut yaprağıyla beslenir; bu yüzden ipekçilik tarih boyunca dut bahçeleriyle birlikte gelişmiştir.'),
  ('Çin\'in yüzyıllar boyunca ipek üretim yöntemini sıkı bir sır olarak saklamasının başlıca amacı neydi?', 'İpek ticaretindeki tekelini korumak', ['İpekböceklerinin nesli tükenmesin diye', 'İpeği yalnız tapınaklarda kullanmak için', 'Komşu ülkelerle savaşı önlemek için'], 'İpek çok değerli bir ihraç malıydı; üretim tekniğinin yayılması Çin\'in bu ticaretteki tekelini ortadan kaldırırdı.'),
  ('Bir kilim dokumacısı, sentetik boya kullanmadan kahverengi tonlarda iplik elde etmek istiyor. Hangi doğal kaynağı kullanması en uygundur?', 'Ceviz kabuğu ve yaprağı', ['Kökboya kökü', 'Cehri meyvesi', 'Safran çiçeğinin tepecikleri'], 'Ceviz yeşil kabuğu ve yaprakları tanen içerir; yün iplikleri kahverengi ve siyaha yakın tonlara boyar.'),
  ('Bebek tulumlarının ağ kısmında, bez değiştirirken kolayca açılıp parmakla bastırınca kapanan küçük metal bağlantılar kullanılır. Bunlara ne ad verilir?', 'Çıtçıt', ['Kopça', 'İlik', 'Toka'], 'Çıtçıt bastırıldığında çıkardığı sesten adını alır; bebek giysilerinde ve montlarda yaygın kullanılır.'),
  ('Bir yanında küçük bir çengel, öbür yanında halka bulunan ve sutyen ya da korse gibi giysilerde kullanılan bağlantı elemanına ne ad verilir?', 'Kopça', ['Çıtçıt', 'Fermuar', 'Perçin'], 'Kopçada çengel halkaya takılarak kapanır; düz ve görünmez bir birleşme sağladığı için iç giyimde tercih edilir.'),
  ('Kumaşta düğmenin geçmesi için açılan ve kenarları sökülmesin diye sık dikişle sağlamlaştırılan yarığa ne ad verilir?', 'İlik', ['Pens', 'Biye', 'Kopça'], 'İlik düğmenin çapına göre açılır; kenarları ilik dikişiyle sarılarak kumaşın sökülmesi önlenir.'),
  ('Kot pantolonların sağ ön cebinin içindeki küçük cep başlangıçta hangi eşya için tasarlanmıştır?', 'Köstekli cep saati', ['Bozuk paralar', 'Kibrit kutusu ve çakmak', 'Ev anahtarı'], '19. yüzyıl işçileri saatlerini köstekle bu küçük cepte taşırdı; cep bugün de kot pantolonların ayırt edici ayrıntısıdır.'),
  ('Bir giysinin bakım etiketinde içinde \'30\' yazan yıkama leğeni simgesi ne anlatır?', 'En çok 30 °C\'de yıkanacağını', ['30 dakikada kuruyacağını', '30 kez yıkamaya dayanacağını', 'Yalnız elde yıkanabileceğini'], 'Leğenin içindeki sayı izin verilen en yüksek su sıcaklığını santigrat derece olarak gösterir.'),
  ('Bakım etiketinde içine bir el çizilmiş yıkama leğeni simgesi ne anlama gelir?', 'Yalnız elde yıkanmalıdır', ['Makinede yıkanmalıdır', 'Kuru temizlemeye verilmelidir', 'Islak hâlde ütülenmelidir'], 'El işaretli leğen giysinin çamaşır makinesine konmaması, ılık suda elle nazikçe yıkanması gerektiğini gösterir.'),
  ('Bir giysinin bakım etiketinde üzeri çarpıyla karalanmış üçgen simgesi görülüyor. Bu ne anlama gelir?', 'Ağartıcı kullanılmamalıdır', ['Ütülenmemelidir', 'Kurutma makinesine konmamalıdır', 'Kuru temizleme yapılmamalıdır'], 'Üçgen ağartma işlemini simgeler; üzerindeki çarpı klor ya da oksijenli hiçbir ağartıcının kullanılmaması gerektiğini bildirir.'),
  ('Kumaş özelliklerinde belirtilen \'gramaj\' neyi gösterir?', 'Bir metrekarenin gram ağırlığını', ['Bir metre ipliğin gram ağırlığını', 'Kumaştaki lif oranını', 'Kumaşın santimetredeki iplik sayısını'], 'Gramaj (g/m²) kumaşın ne kadar ağır ve kalın olduğunu anlatır; yazlık tişörtler düşük, kışlık sweatshirtler yüksek gramajlıdır.'),
  ('Saydam ve ince bir çorap almak isteyen bir kadın, paketlerde \'15 den\' ve \'60 den\' yazan iki çorap görüyor. Hangisini seçmelidir?', '15 denyeliği; denye küçüldükçe iplik incelir', ['60 denyeliği; denye büyüdükçe iplik incelir', '60 denyeliği; çünkü örgüsü daha seyrektir', 'Fark etmez; denye çorabın rengini gösterir'], 'Denye ne kadar küçükse iplik o kadar incedir; 15 denyelik bir çorap 40 denyelik bir çoraptan daha saydamdır.'),
  ('Bir kişi yeni kazağının kol altlarında ve yanlarında, sürtünen yerlerde küçük lif topakçıkları oluştuğunu görüyor. Bu kusurun adı nedir?', 'Boncuklanma', ['Keçeleşme', 'Çekme', 'Renk solması'], 'Boncuklanma (pilling) liflerin yüzeye çıkıp birbirine dolanmasıyla oluşur; kısa lifli ve gevşek bükümlü ipliklerde daha sık görülür.'),
  ('1,5 m × 2 m boyutlarındaki bir kumaş parçası 600 gram geliyor. Bu kumaşın gramajı kaç g/m²\'dir?', '200', ['300', '400', '900'], 'Alan 1,5 × 2 = 3 m²\'dir; 600 g / 3 m² = 200 g/m².'),
  ('500 metre uzunluğundaki bir iplik çilesi 10 gram geliyor. Bu ipliğin numarası kaç tex\'tir?', '20', ['5', '50', '0,02'], 'Tex, 1000 metre ipliğin gram ağırlığıdır: 10 g / 500 m × 1000 m = 20 g, yani 20 tex.'),
  ('Bir atölyede bir gömlek için 1,6 metre kumaş gerekiyor. 25 gömlek dikilecek ve kesimde %4 fire olacağı hesaplanıyor. Toplam kaç metre kumaş alınmalıdır?', '41,6', ['40', '41,2', '64'], 'Net ihtiyaç 25 × 1,6 = 40 m\'dir; %4 fire eklenince 40 × 1,04 = 41,6 m kumaş gerekir.'),
  ('Yıkamadan önce 50 cm olarak ölçülen bir kumaş numunesi yıkama ve kurutmadan sonra 48 cm geliyor. Kumaşın çekme oranı yüzde kaçtır?', '4', ['2', '8', '96'], 'Çekme miktarı 50 − 48 = 2 cm\'dir; 2 / 50 × 100 = %4.'),
  ('Bir çarşaf kumaşında bir inçte 120 çözgü ve 80 atkı ipliği bulunuyor. Bu kumaşın iplik sayısı (thread count) kaçtır?', '200', ['120', '9600', '40'], 'İplik sayısı bir inç karedeki atkı ve çözgü ipliklerinin toplamıdır: 120 + 80 = 200.'),
  ('Askerî ceketlerde omuzlara takılan ve çoğu zaman rütbe gösteren süslü parçaya ne ad verilir?', 'Apolet', ['Kordon', 'Brövet', 'Armağan'], 'Apolet (Fr. épaulette, küçük omuz) üzerindeki işaretler ve saçaklar rütbeyi gösterir; trençkotlardaki omuz kayışları da bu geleneğin izidir.'),
  ('ABD İç Savaşı\'nda Güney (Konfedere) ordusunun üniformaları hangi renkle özdeşleşmiştir?', 'Gri', ['Lacivert', 'Kırmızı', 'Haki'], 'Kuzey (Birlik) ordusu lacivert, Güney ordusu gri üniformalarıyla anılır; bu yüzden savaşa \'mavi ile gri\'nin çatışması da denir.'),
  ('18. yüzyılda Amerikan kolonistleri İngiliz askerlerini üniformalarının renginden ötürü nasıl adlandırırdı?', 'Kırmızı ceketliler', ['Mavi üniformalı ceketliler', 'Yeşil şapkalılar', 'Siyah çizmeliler'], 'İngiliz piyadesinin kırmızı ceketleri \'redcoats\' adını doğurdu; kırmızı boya ucuz, bol ve uzaktan tanınabilir olduğu için tercih edilmişti.'),
  ('Polyester ve akrilik giysilerin çamaşır makinesinde yıkanmasının denizler açısından en çok tartışılan çevresel etkisi nedir?', 'Suya mikroplastik lifler salması', ['Deniz suyunun tuzluluğunu artırması', 'Denizlerde petrol sızıntısı yaratması', 'Suyun sıcaklığını yükseltmesi'], 'Her yıkamada sentetik kumaşlardan kopan çok ince lifler arıtmalardan kaçarak denizlere ulaşabilir ve besin zincirine karışabilir.'),
  ('Organik pamuğu geleneksel yöntemlerle yetiştirilen pamuktan ayıran temel özellik hangisidir?', 'Sentetik ilaç ve gübre kullanılmaması', ['Liflerinin doğal olarak renkli olması', 'Yalnız elle toplanması', 'Tohumlarının laboratuvarda üretilmesi'], 'Organik pamuk sertifikalı üretimde sentetik pestisit, yapay gübre ve genetiği değiştirilmiş tohum kullanılmaz.'),
  ('Eski bir kot pantolonun kesilip tasarımla daha değerli bir çantaya dönüştürülmesi hangi kavramla anlatılır?', 'İleri dönüşüm', ['Hızlı moda', 'Yeşil aklama', 'Kapsül gardırop'], 'İleri dönüşüm (upcycling) atık ya da kullanılmayan bir ürünü daha değerli yeni bir ürüne dönüştürmektir.'),
  ('Bir giyim markasının çevreye zararlı üretimini abartılı \'doğal\' ve \'yeşil\' sloganlarla gizlemeye çalışmasına ne ad verilir?', 'Yeşil aklama', ['İleri dönüşüm', 'Yavaş moda', 'Adil ticaret'], 'Yeşil aklama (greenwashing) tüketiciyi çevreci olduğuna inandırmak için yanıltıcı iddialar kullanmaktır.'),
  ('Her sezon yeni giysi almak yerine az sayıda kaliteli, uzun ömürlü ve yerel üretilmiş giysi almaya karar veren bir tüketici hangi yaklaşımı benimsemiştir?', 'Yavaş moda', ['Hızlı moda', 'Haute couture', 'Sokak modası'], 'Yavaş moda, hızlı modanın sürekli tüketim temposuna karşı çıkar; giysilerin daha uzun kullanılmasını ve onarılmasını önerir.'),
  ('Hangi tenis turnuvası oyuncuların neredeyse tümüyle beyaz giyinmesini isteyen köklü kıyafet kuralıyla bilinir?', 'Wimbledon', ['Roland Garros', 'ABD Açık', 'Avustralya Açık'], 'Wimbledon\'ın beyaz kıyafet kuralı 19. yüzyıla uzanır; ter lekelerinin beyazda daha az görüneceği düşüncesi bu geleneğin kaynaklarından biri sayılır.'),
  ('Soğuk suda sörf yapacak birine, içinde küçük gaz kabarcıkları bulunan ve ısı yalıtımı sağlayan sentetik bir kauçuktan yapılmış ıslak giysi öneriliyor. Bu malzeme hangisidir?', 'Neopren', ['Doğal lateks', 'Naylon', 'Akrilik'], 'Neoprenin içindeki gaz kabarcıkları ısı yalıtımı sağlar; giysiyle ten arasındaki ince su katmanı vücut ısısıyla ısınır.'),
  ('19. yüzyılda korseyle elde edilen, omuz ve kalçası geniş, beli çok ince kadın siluetine ne ad verilir?', 'Kum saati siluet', ['Ampir siluet', 'A kesim siluet', 'Çuval (sack) siluet'], 'Kum saati siluetinde dar bel, kabarık etek ve geniş omuzlarla vurgulanırdı; bu görünüm korsenin sıkılmasıyla sağlanıyordu.'),
  ('Çorapları uyluk hizasında tutmak için kullanılan lastikli bant ya da askıya ne ad verilir?', 'Jartiyer', ['Korse', 'Kopça', 'Tela şeridi'], 'Jartiyer (Fr. jarretière, diz arkası) külotlu çoraplardan önce çorabın kaymasını önleyen temel aksesuardı.'),
  ('Moda tasarımında bir giysinin dış hatlarının oluşturduğu genel biçime, örneğin A kesim ya da kum saati görünümüne ne ad verilir?', 'Siluet', ['Patron', 'Pastal', 'Prova'], 'Siluet giysinin uzaktan algılanan genel biçimidir; moda tarihindeki dönemler çoğu zaman siluetleriyle ayırt edilir.'),
  ('Bir giyim markası aynı tişörtü kadın ve erkek müşterilere tek bir beden tablosuyla satıyor. Bu ürün hangi kavramla nitelendirilir?', 'Uniseks giysi', ['Haute couture', 'Kapsül giysi', 'Vintage (eski dönem) giysi'], 'Uniseks giysiler cinsiyete göre ayrılmayan kesim ve bedenlerde üretilir; tişört ve kot pantolon bunun bilinen örnekleridir.'),
  ('Trençkot ve küçük siyah elbise gibi onlarca yıl boyunca modadan düşmeyen parçalar moda döngüsü açısından nasıl nitelendirilir?', 'Klasik', ['Geçici heves', 'Avangart', 'Kostüm'], 'Klasikler uzun süre kabul görmeye devam eder; geçici hevesler (fad) ise hızla yayılıp kısa sürede unutulur.'),
  ('Bir tasarımcı koleksiyonunda süslemeyi tümüyle kaldırıp yalnız nötr renkler ve sade kesimler kullanıyor. Bu yaklaşım hangi moda akımıyla örtüşür?', 'Minimalizm', ['Barok', 'Grunge', 'Maksimalizm'], 'Minimalist moda 1980\'lerin gösterişli giyimine tepki olarak sadeliği ve iyi kesimi öne çıkardı.'),
  ('Bir kişi lacivert blazer, bej chino pantolon ve düğmeli yakalı gömlekle Amerikan kolej öğrencisi görünümü yaratıyor. Benimsediği stil hangisidir?', 'Preppy', ['Grunge', 'Punk', 'Gotik (dark) stil'], 'Preppy adı özel hazırlık okullarından (prep school) gelir; Ivy League stili olarak da bilinir.'),
  ('Üzerine desen basılmış, ucuz ve ince pamuklu kumaşa Türkçede ne ad verilir?', 'Basma', ['Kemha', 'Tafta', 'Kaşe yünlü'], 'Basma halk giyiminde yaygın kullanılan baskılı pamukludur; Cumhuriyet döneminde Nazilli gibi fabrikalarda büyük ölçekte üretilmiştir.'),
  ('Bir anne bebeği için ince, yumuşak ve sık dokunmuş beyaz pamuklu bezden mendil ve iç çamaşırı dikmek istiyor. Hangi kumaşı almalıdır?', 'Patiska', ['Kanvas', 'Brokar', 'Kaşe yünlü kumaş'], 'Patiska ince pamuk ipliklerinden bezayağı örgüyle sık dokunan, yumuşak ve hafif parlak bir kumaştır.'),
  ('Kampa gidecek biri hafif, çabuk kuruyan ve ıslakken bile sıcak tutan, şardonlanmış sentetik örme kumaştan bir ara katman ceketi arıyor. Hangi kumaş en uygundur?', 'Polar', ['Kadife', 'Saten', 'Şifon'], 'Polar polyesterden örülüp tüylendirilir; yüne göre hafiftir ve nemi tutmaz, bu yüzden doğa sporlarında yaygındır.'),
  ('Bir sahne kostümcüsü ışık altında parıldayacak, metal ya da metalik görünümlü ipliklerle dokunmuş bir kumaş arıyor. Hangisini seçmelidir?', 'Lame', ['Pazen', 'Patiska', 'Kanvas'], 'Lame kumaşta ince metal şeritler ya da metalize iplikler atkı olarak kullanılır; ışıkta parıldar.'),
  ('Bir çadır üreticisi, küçük bir yırtığın kumaş boyunca büyümesini engelleyen ve ızgara biçiminde kalın takviye iplikleri bulunan bir kumaş arıyor. Hangisini seçmelidir?', 'Ripstop', ['Jakar', 'Dimi', 'Saten örgü'], 'Ripstop kumaşlar paraşüt, çadır ve outdoor giyimde kullanılır; takviye iplikleri yırtığın ilerlemesini durdurur.'),
  ('Bir kişi derinin iç yüzü zımparalanmış, kadifemsi ve mat yüzeyli bir ayakkabı alıyor; satıcı ayakkabıyı yağmurda giymemesini öğütlüyor. Bu deri türü hangisidir?', 'Süet', ['Rugan', 'Kösele', 'Napa'], 'Süet derinin iç yüzünden elde edildiği için yumuşak ve tüylüdür ama suya ve lekeye karşı hassastır.'),
  ('Resmî bir gece için ayna gibi parlak yüzeyli siyah ayakkabı isteyen bir müşteriye hangi deri türü önerilmelidir?', 'Rugan', ['Süet', 'Nubuk', 'Kösele'], 'Rugan ayakkabılar parlak yüzeyleri nedeniyle resmî ve gece kıyafetleriyle tercih edilir.'),
  ('Bir kunduracı klasik bir erkek ayakkabısına sert ve dayanıklı, bitkisel tabaklanmış kalın deriden bir taban yapmak istiyor. Hangi deriyi kullanmalıdır?', 'Kösele', ['Süet', 'Napa derisi', 'Nubuk'], 'Kösele sert ve dayanıklıdır; klasik ayakkabıların deri tabanları ve kemerler bu deriden yapılır.'),
  ('Ham hayvan derisinin çürümeyecek, esnek ve dayanıklı hâle getirilmesi için kimyasal ya da bitkisel maddelerle işlenmesine ne ad verilir?', 'Tabaklama', ['Kırkım', 'Şardon', 'Merserizasyon'], 'Tabaklama derideki proteinleri kararlı hâle getirir; tabaklanmamış deri kuruyunca sertleşir ve nemde çürür.'),
  ('Bir kişi tek bir çengelli iğne ve yün ipliğiyle ilmekleri birbirine geçirerek bir bere örüyor. Uyguladığı teknik hangisidir?', 'Tığ işi', ['Şiş örgüsü', 'Mekik oyası', 'Kanaviçe'], 'Tığ işinde her seferinde tek bir aktif ilmek bulunur; şiş örgüsünde ise çok sayıda ilmek şişin üzerinde bekler.'),
  ('Bir öğrenci kareli ve delikli bir kumaşa, şemadaki kareleri sayarak X biçimli ilmeklerle bir çiçek deseni işliyor. Uyguladığı nakış türü hangisidir?', 'Kanaviçe', ['Aplike', 'Kapitone', 'Ajur'], 'Kanaviçe (çarpı işi) desenleri kareli kâğıda çizilmiş şemalardan sayılarak işlenir.'),
  ('Bir anne çocuğunun tişörtüne başka bir kumaştan kestiği ayı figürünü kenarlarından dikerek ekliyor. Kullandığı süsleme tekniği hangisidir?', 'Aplike', ['Kanaviçe', 'Ajur', 'Kapitone'], 'Aplikede kesilen parçaların kenarları dikişle zemine tutturulur; çocuk giysilerinde ve örtülerde sık görülür.'),
  ('Bir yorgan ustası iki kat kumaş arasına pamuk koyup belirli aralıklarla dikerek kabarık karolar oluşturuyor. Uyguladığı teknik hangisidir?', 'Kapitone', ['Aplike', 'Ajur', 'Kanaviçe'], 'Kapitone hem süs hem ısı yalıtımı sağlar; şişme montlar ve yorganlar bu ilkeyle yapılır.'),
  ('Bir kişi artık kumaş parçalarını kenar kenara dikerek rengârenk bir yatak örtüsü yapıyor. Yaptığı işin adı nedir?', 'Kırkyama', ['Kanaviçe', 'Ajur', 'Tığ (kroşe) işi'], 'Kırkyama (patchwork) artık kumaşları değerlendirmenin geleneksel yoludur; yorgan ve örtülerde yaygındır.'),
  ('Beyaz gelinliğin Batı\'da yaygın bir gelenek hâline gelmesinde hangi kraliyet düğünü etkili olmuştur?', 'Kraliçe Victoria\'nın 1840 düğünü', ['Marie Antoinette\'in 1770\'teki düğünü', 'XIV. Louis\'nin 1660\'taki düğünü', 'Prenses Diana\'nın 1981\'deki düğünü'], 'Victoria\'nın beyaz saten ve dantel gelinliği gazetelerde geniş yer buldu; o güne dek gelinler çoğunlukla en iyi renkli elbiselerini giyerdi.'),
  ('İngiliz düğün geleneğindeki \'bir şey eski, bir şey yeni, bir şey ödünç, bir şey mavi\' sözü neyi anlatır?', 'Gelinin taşıyacağı uğurlu şeyleri', ['Damadın gelin ailesine vereceği armağanları', 'Düğün yemeğinde sunulacak yemekleri', 'Konukların düğüne getireceği hediyeleri'], 'Bu tekerleme gelinin geçmişle bağını, geleceğe umudu, sevgiyi ve sadakati simgeleyen dört nesne taşımasını öğütler.'),
  ('Londra\'da kraliyet muhafızlarının taktığı uzun, siyah kürk başlığa ne ad verilir?', 'Bearskin', ['Melon şapka', 'Kasket', 'Bere'], 'Bearskin (ayı postu) başlıklar Waterloo\'dan sonra bazı muhafız alaylarının simgesi olmuştur; geleneksel olarak ayı kürkünden yapılır.'),
  ('Fabrika ve atölye işçileri için \'mavi yakalı\' deyiminin kullanılmasının kaynağı nedir?', 'Kiri az gösteren mavi giysiler giymeleri', ['Mavi gözlü göçmenler olmaları', 'Mavi bayraklı sendikalara üye olmaları', 'Yalnız denizcilik sektöründe çalışmaları'], 'Bedensel işlerde çalışanlar dayanıklı ve kiri belli etmeyen mavi kumaşlar giyerdi; büro çalışanları ise beyaz gömlekleri nedeniyle \'beyaz yakalı\' diye anılır.'),
  ('Bir oto tamircisi, altındaki giysileri yağdan korumak için gövdesini ve bacaklarını tek parça saran bir iş giysisi giyiyor. Bu giysinin adı nedir?', 'Tulum', ['Önlük', 'Cepken', 'Yelek'], 'Tulum giysinin altına giyilenleri kir ve yağdan korur; işçi giysisi olarak doğmuş, sonra moda giyime de girmiştir.'),
  ('Gece davetine gidecek biri yalnız telefonunu ve rujunu taşıyabileceği, sapı ve askısı olmayan küçük bir çanta arıyor. Hangisini seçmelidir?', 'Portföy', ['Sırt çantası', 'Heybe', 'Postacı (askılı) çantası'], 'Portföy çantalar genellikle gece kıyafetiyle kullanılır; içine yalnız küçük kişisel eşyalar sığar.'),
  ('1960\'ların ortasında çok zayıf yapısı, kısa saçları ve belirgin kirpikleriyle \'Swinging London\' döneminin yüzü olan İngiliz manken kimdir?', 'Twiggy', ['Kate Moss', 'Naomi Campbell', 'Jean Shrimpton'], 'Lesley Hornby, \'Twiggy\' (dal gibi) lakabıyla dönemin androjen ve genç görünümünü simgeledi.'),
  ('Bir öğrenci \'Kot pantolon ilk ortaya çıktığında gençler için bir moda giysisi olarak tasarlanmıştı.\' diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanlıştır; kot önce işçiler için iş giysisiydi', ['Doğrudur; ilk kot pantolonlar okul üniforması olarak satıldı', 'Doğrudur; kot pantolonu ilk Paris modacıları tasarladı', 'Yanlıştır; kot önce yalnız kadınlar için üretildi'], '19. yüzyıl ABD\'sinde kot pantolon madencilerin ve işçilerin yıpranmayan iş pantolonuydu; gençlik modasına ancak 20. yüzyıl ortasında girdi.'),
  ('Bir tasarımcı aynı kalıptan şifon ve kanvas iki etek dikiyor; şifon etek yumuşakça sarkarken kanvas etek dik duruyor. İki kumaş arasındaki bu fark hangi özellikle açıklanır?', 'Döküm', ['Gramaj', 'Haslık', 'Boncuklanma'], 'Döküm (drape) kumaşın lif, iplik ve örgü yapısına bağlıdır; şifon akışkan, kanvas ise sert bir döküm verir.'),
  ('Bir terzi 1980\'lerden esinlenen bir ceketin omuzlarının geniş ve dik görünmesini istiyor. Omuz kısmının içine ne yerleştirmelidir?', 'Vatka', ['Tela', 'Biye', 'Pens'], 'Vatkalar 1940\'larda ve 1980\'lerde geniş omuzlu siluetlerle çok büyümüş; günümüz ceketlerinde daha ince kullanılır.'),
  ('Ceketin ön tarafında göğüs üzerinde dışa doğru kıvrılarak yakayla birleşen parçaya ne ad verilir?', 'Klapa', ['Pat', 'Manşet', 'Yırtmaç'], 'Klapanın genişliği ve biçimi (çentikli, sivri, şal) ceketin üslubunu belirleyen en önemli ayrıntılardandır.'),
  ('Bir sweatshirt tasarımcısı ön tarafa, iki yandan el sokulabilen tek parça büyük bir cep ekliyor. Bu cebin adı nedir?', 'Kanguru cep', ['Fileto cep', 'Saat cebi', 'Körüklü cep'], 'Kanguru cep, kangurunun yavrusunu taşıdığı karın kesesine benzetildiği için bu adı almıştır.'),
  ('Bir terzi bir bluzun yaka kenarına dalgalı biçimde dökülen bir kumaş katı ekliyor. Eklediği parçanın adı nedir?', 'Volan', ['Pens', 'Pili', 'Biye'], 'Volan (fırfır) genellikle verev ya da daire biçiminde kesilir; böylece kenarda dalgalı bir hareket kazanır.'),
  ('Bir gelin eteğinin daha kabarık görünmesini istiyor. Terzi eteğin altına hangi giysinin giyilmesini önermelidir?', 'Jüpon', ['Kombinezon', 'Jartiyer', 'Korse'], 'Jüpon özellikle gelinlik ve 1950\'lerin geniş etekli elbiselerinde hacim vermek için kullanılır.'),
  ('İnce ve yarı saydam bir elbise giyecek biri, elbisenin tene yapışmasını ve içini göstermesini önlemek için altına hangi giysiyi giymelidir?', 'Kombinezon', ['Jüpon', 'Bolero', 'Korse'], 'Kombinezon kaygan kumaşı sayesinde elbisenin rahat dökülmesini sağlar; ince kumaşların saydamlığını da örter.'),
  ('Bir iş görüşmesine gidecek kadın aynı kumaştan dikilmiş ceket ve etekten oluşan bir takım alıyor. Aldığı takımın adı nedir?', 'Döpiyes', ['Tulum', 'Kombinezon', 'Bolero'], 'Döpiyes (Fr. deux pièces, iki parça) iş ve resmî ortamlarda giyilen klasik bir kadın takımıdır.'),
  ('Askılı bir gece elbisesinin omuzlarını örtmek için bel hizasının üstünde biten, önü açık kısa bir ceket arayan birine ne önerilmelidir?', 'Bolero', ['Trençkot', 'Blazer', 'Kaban'], 'Bolero İspanyol dans giysilerinden esinlenmiştir; genellikle elbisenin üzerine omuzları örtmek için giyilir.'),
  ('Bir kazak %60 pamuk ve %40 akrilik karışımlı iplikten örülmüştür ve 500 gram gelmektedir. Kazakta yaklaşık kaç gram akrilik vardır?', '200', ['300', '40', '250'], 'Akrilik oranı %40\'tır: 500 × 0,40 = 200 gram.'),
  ('Bir koyundan bir yılda 4 kilogram ham yapağı kırkılıyor. Yıkama sırasında yağ, kir ve yabancı maddeler nedeniyle ağırlığın %40\'ı kaybediliyorsa geriye kaç kilogram temiz yün kalır?', '2,4', ['1,6', '3,6', '2,0'], 'Kalan oran %60\'tır: 4 × 0,60 = 2,4 kg temiz yün.'),
  ('Bir taytın kumaşı %92 polyamid ve %8 elastandan oluşmaktadır ve tayt 250 gram gelmektedir. Tayttaki elastan miktarı kaç gramdır?', '20', ['8', '92', '25'], 'Elastan oranı %8\'dir: 250 × 0,08 = 20 gram.'),
  ('Kalıbı 40 cm genişliğinde olan bir parçaya her iki yanına 1,5 cm dikiş payı eklenecektir. Kumaş kaç santimetre genişliğinde kesilmelidir?', '43', ['41,5', '46', '40'], 'Her iki yana 1,5 cm eklenir: 40 + 2 × 1,5 = 43 cm.'),
  ('Bir pamuklu tişörtün üretim aşamaları doğru sırayla hangisinde verilmiştir?', 'Lif, eğirme, örme, terbiye ve boyama, dikim', ['Eğirme, lif, dikim, örme, boyama', 'Örme, eğirme, lif, dikim, boyama', 'Dikim, boyama, örme, eğirme, lif'], 'Önce lif elde edilir, eğrilerek iplik yapılır, iplikten kumaş örülür, kumaş terbiye edilip boyanır, son olarak kesilip dikilir.'),
  ('Bir satıcı \'Bu ipek gömlek tümüyle bitkisel kökenli olduğu için hayvansal ürün kullanmayanlara uygundur.\' diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanlıştır; ipek ipekböceğinin salgıladığı bir proteindir', ['Doğrudur; ipek dut ağacından elde edilir', 'Doğrudur; ipek pamuk bitkisinden çekilir', 'Yanlıştır; ipek petrolden üretilen sentetik bir liftir'], 'İpek, ipekböceği tırtılının koza örerken salgıladığı hayvansal bir liftir; dut yalnız böceğin besinidir.'),
  ('Evde peynir yapan biri, kesilmiş sütün suyunu süzmek için ince ve seyrek dokunmuş pamuklu bir beze ihtiyaç duyuyor. Hangi bezi kullanmalıdır?', 'Tülbent', ['Kanvas', 'Kaşe', 'Kadife'], 'Tülbent hafif ve havadar bir bezdir; Anadolu\'da başörtüsü ve yazma zemini olarak da yaygın kullanılmıştır.'),
  ('Bir tasarımcının koleksiyonuna esin kaynağı olan görselleri, kumaş örneklerini ve renkleri bir araya getirdiği panoya ne ad verilir?', 'Esin panosu', ['Teknik föy', 'Pastal planı', 'Beden tablosu'], 'Esin panosu koleksiyonun havasını, renk paletini ve temasını belirlemeye yardım eder; tasarım sürecinin ilk adımlarındandır.'),
  ('Bir marka yeni ceket modelini fabrikada binlerce adet üretmeden önce kalıbı ve dikimi denemek için tek bir örnek diktiriyor. Bu örneğe ne ad verilir?', 'Numune', ['Pastal', 'Defile', 'Patron'], 'Numune üzerinde ölçü ve dikim sorunları belirlenir; onaylandıktan sonra seri üretime geçilir.'),
  ('Bebek tenine uygun, nefes alan, alerji yapma olasılığı düşük ve yüksek ısıda yıkanabilen bir zıbın kumaşı için en uygun lif hangisidir?', 'Pamuk', ['Akrilik', 'Polyester', 'Naylon'], 'Pamuk yumuşak, emici ve nefes alan bir liftir; yüksek sıcaklıkta yıkanmaya dayanır. Sentetik lifler teri emmez ve yüksek ısıya dayanıksızdır.'),
  ('Çölde gündüz yürüyüş yapacak bir gezgin için güneşten ve sıcaktan korunma açısından en uygun giyim seçimi hangisidir?', 'Açık renkli, bol ve uzun kollu hafif giysiler', ['Koyu renkli, dar ve kısa kollu giysiler', 'Kalın yünlü ve vücuda oturan giysiler', 'Siyah, su geçirmez ve kapalı bir yağmurluk'], 'Açık renk güneş ışığını daha çok yansıtır; bol ve uzun kollu giysiler teni güneşten korurken giysiyle ten arasında hava dolaşımına izin verir.'),
  ('40 tex numaralı bir ipliğin 250 metresi kaç gram gelir?', '10', ['40', '160', '2,5'], '40 tex, 1000 metresi 40 gram olan iplik demektir; 250 metre bunun dörtte biridir: 40 × 250 / 1000 = 10 gram.'),
  ('Gramajı 180 g/m² olan bir tişört kumaşından, bir tişört için 0,5 metrekare kumaş kullanılıyor. Tişörtün kumaş ağırlığı kaç gramdır?', '90', ['360', '180', '45'], 'Ağırlık = gramaj × alan = 180 × 0,5 = 90 gram.'),
  ('Eni 140 cm olan bir kumaştan 2,5 metre satın alan bir müşteri toplam kaç metrekare kumaş almış olur?', '3,5', ['35', '1,4', '2,5'], 'Alan = en × boy = 1,4 m × 2,5 m = 3,5 m².'),
  ('Yeni ve koyu renkli pamuklu bir tişörtün ilk yıkamalarda beyaz çamaşırlardan ayrı yıkanması neden önerilir?', 'Liften akabilecek fazla boyanın beyazları boyayabilmesi', ['Koyu tişörtün beyazları yırtabilmesi', 'Beyaz çamaşırların koyu tişörtü ağartması', 'Koyu renkli kumaşların daha ağır olması'], 'Boyamadan sonra lifte tam bağlanmamış boya kalabilir; bu boya yıkama suyuna geçip açık renkli giysilere bulaşabilir.'),
  ('Koyu renkli bir kot pantolonun renginin solmasını geciktirmek için hangi yıkama yöntemi önerilir?', 'Ters çevirip soğuk suda yıkamak', ['Yüz derecede kaynatarak yıkamak', 'Çamaşır suyuyla bekletmek', 'Her gün sıcak suda yıkamak'], 'Ters çevirmek yüzeydeki sürtünmeyi azaltır, soğuk su ise indigonun daha az akmasını sağlar.'),
  ('Yün ve ipek giysiler yaz aylarında kaldırılırken dolaplara lavanta ya da sedir ağacı parçaları konmasının amacı nedir?', 'Protein lifleriyle beslenen güvelerden korumak', ['Giysilerin rengini koyulaştırmak', 'Kumaşı ütüsüz düzleştirmek', 'Giysilerin çekmesini sağlamak'], 'Güve larvaları yün ve ipekteki keratin ve fibroini sindirebilir; lavanta ve sedirin kokusu güveleri uzaklaştırmaya yardım eder.'),
  ('Haute couture giysilerin çok pahalı olmasının başlıca nedeni hangisidir?', 'Kişiye özel kalıp ve yüzlerce saatlik el işçiliği gerektirmesi', ['Yalnız sentetik kumaştan dikilmesi', 'Fabrikalarda çok büyük sayılarda üretilmesi', 'Yalnız tek bir bedende yapılması'], 'Bir haute couture giysi müşterinin ölçülerine göre birçok provayla, büyük ölçüde elde dikilir; nakış gibi işler yüzlerce saat sürebilir.'),
];
